import { useRef, useCallback } from 'react';

/**
 * useLUT Hook (Hald-8 Version)
 * Specifically designed for Hald CLUT images (512x512) generated by ImageMagick or Lightroom.
 */
export const useLUT = () => {
  const lutCache = useRef<Map<string, ImageData>>(new Map());

  const loadLUT = useCallback(async (lutUrl: string): Promise<ImageData | null> => {
    if (lutCache.current.has(lutUrl)) return lutCache.current.get(lutUrl)!;
    try {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.src = lutUrl;
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
      });
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d', { willReadFrequently: true })!;
      ctx.drawImage(img, 0, 0);
      const data = ctx.getImageData(0, 0, img.width, img.height);
      lutCache.current.set(lutUrl, data);
      return data;
    } catch (err) { return null; }
  }, []);

  const applyLUT = useCallback((ctx: CanvasRenderingContext2D, lutData: ImageData, width: number, height: number) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const lut = lutData.data;
    
    // Hald-8 Level: 64x64x64 colors
    const L = 64; 

    for (let i = 0; i < data.length; i += 4) {
      // Scale R,G,B to 0-63 range
      const r = Math.round(data[i]     * 63 / 255);
      const g = Math.round(data[i + 1] * 63 / 255);
      const b = Math.round(data[i + 2] * 63 / 255);

      // Hald-8 Linear Mapping: Index = R + (G * 64) + (B * 64 * 64)
      const index = r + (g * L) + (b * L * L);

      // Map linear index to 512x512 image coordinates
      const x = index % 512;
      const y = Math.floor(index / 512);

      const lutIdx = (y * 512 + x) * 4;

      // Update the pixel with the LUT color
      data[i]     = lut[lutIdx];
      data[i + 1] = lut[lutIdx + 1];
      data[i + 2] = lut[lutIdx + 2];
      // data[i+3] (alpha) remains original
    }

    ctx.putImageData(imageData, 0, 0);
  }, []);

  return { loadLUT, applyLUT };
};
